// Writes src/icons.js from the Tabler outline set (only the icons the prototype uses).
// Usage: npm run icons   (needs the devDependency @tabler/icons; the generated file is committed)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
const NAMES = `layout-dashboard map-2 droplets copy building-store message-report settings help-circle logout bell search
chevron-left chevron-right chevron-down chevron-up home plus minus current-location photo map-pin check x alert-triangle
alert-circle info-circle clock lock flag dots-vertical building eye eye-off calendar upload download file-text trash edit
filter menu-2 sun moon device-desktop circle-check circle-x user users shield-check refresh send external-link arrow-right
arrow-left sparkles qrcode wifi-off cloud-off list layout-grid table tool droplet droplet-off bucket-droplet ripple
building-factory-2 cylinder steering-wheel building-broadcast-tower database mail phone world language device-mobile
history link message star loader-2 checklist user-check camera file-export building-community truck receipt user-plus key
layers-subtract stack-2 selector arrows-sort sort-ascending sort-descending circle clock-hour-3 player-play microphone
flag-check target click hourglass-low cloud-check coin tag route message-circle bulb wallet eye-check thumb-up thumb-down
adjustments-horizontal zoom-in zoom-out notes circle-dashed line compass`.split(/\s+/).filter(Boolean);
const out = {}; const missing = [];
for (const n of NAMES) {
  const f = `node_modules/@tabler/icons/icons/outline/${n}.svg`;
  if (!existsSync(f)) { missing.push(n); continue; }
  const svg = readFileSync(f, "utf8");
  out[n] = [...svg.matchAll(/<path[^>]*\sd="([^"]+)"/g)].map((m) => m[1]).filter((d) => d !== "M0 0h24v24H0z");
}
writeFileSync("src/icons.js", "// Generated by scripts/gen-icons.mjs from Tabler Icons (MIT). Do not edit by hand.\nexport const ICONS = " + JSON.stringify(out) + ";\n");
console.log(`icons: ${Object.keys(out).length} written` + (missing.length ? `, missing: ${missing.join(", ")}` : ""));
